import { useEffect } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan, hasFeature } from "../lib/plans";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const [config, subscription] = await Promise.all([
    db.recommenderConfig.findUnique({ where: { shop } }),
    db.subscription.findUnique({ where: { shop } }),
  ]);

  const plan = getPlan(subscription?.planId ?? "free");
  const canUseAi = hasFeature(plan.id, "aiRecommender");
  const canUseAdvanced = hasFeature(plan.id, "advancedAi");

  return {
    config: config ?? {
      enabled: false,
      algorithm: "basic",
      bodyTypes: "[]",
      sizingRules: "{}",
    },
    plan,
    canUseAi,
    canUseAdvanced,
  };
};

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    switch (intent) {
      case "toggle": {
        const subscription = await db.subscription.findUnique({ where: { shop } });
        const plan = getPlan(subscription?.planId ?? "free");
        if (!hasFeature(plan.id, "aiRecommender")) {
          return { error: "AI recommender requires Growth plan or higher" };
        }

        const current = await db.recommenderConfig.findUnique({ where: { shop } });
        await db.recommenderConfig.upsert({
          where: { shop },
          update: { enabled: !current?.enabled },
          create: { shop, enabled: true },
        });

        return { ok: true, message: current?.enabled ? "AI Recommender disabled" : "AI Recommender enabled" };
      }

      case "update-settings": {
        const algorithm = (formData.get("algorithm") as string) || "basic";
        const bodyTypes = formData.get("bodyTypes") as string || "[]";

        await db.recommenderConfig.upsert({
          where: { shop },
          update: { algorithm, bodyTypes },
          create: { shop, algorithm, bodyTypes, enabled: true },
        });

        return { ok: true, message: "Settings saved" };
      }

      default:
        return { error: "Unknown action" };
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : "An unexpected error occurred";
    return { error: message };
  }
};

export default function Recommender() {
  const { config, plan, canUseAi, canUseAdvanced } = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();

  useEffect(() => {
    if (fetcher.data && "ok" in fetcher.data && fetcher.data.ok) {
      shopify.toast.show(fetcher.data.message ?? "Success");
    } else if (fetcher.data && "error" in fetcher.data) {
      shopify.toast.show(fetcher.data.error ?? "Error", { isError: true });
    }
  }, [fetcher.data, shopify]);

  const isLoading = fetcher.state !== "idle";

  return (
    <s-page heading="AI Size Recommender">
      {/* Upgrade Banner */}
      {!canUseAi && (
        <s-section>
          <s-box padding="base" borderWidth="base" borderRadius="base" background="subdued">
            <s-stack direction="block" gap="base">
              <s-text variant="headingMd">Unlock AI Size Recommendations</s-text>
              <s-paragraph>
                Help customers find their perfect size with AI-powered recommendations
                based on height, weight, and body type. Available on Growth plan and above.
              </s-paragraph>
              <s-button href="/app/pricing" variant="primary">
                Upgrade to Growth — $9.99/mo
              </s-button>
            </s-stack>
          </s-box>
        </s-section>
      )}

      {/* AI Toggle */}
      {canUseAi && (
        <s-section heading="Recommender Status">
          <s-stack direction="inline" gap="base">
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-stack direction="block" gap="tight">
                <s-text variant="headingSm">
                  Status: {config.enabled ? "Active" : "Disabled"}
                </s-text>
                <s-text variant="bodySm" tone="subdued">
                  {config.enabled
                    ? "Customers can get AI-powered size recommendations on your storefront"
                    : "Enable to show the 'Find My Size' button on product pages"}
                </s-text>
                <fetcher.Form method="post">
                  <input type="hidden" name="intent" value="toggle" />
                  <s-button
                    submit
                    variant={config.enabled ? "tertiary" : "primary"}
                    loading={isLoading}
                  >
                    {config.enabled ? "Disable Recommender" : "Enable Recommender"}
                  </s-button>
                </fetcher.Form>
              </s-stack>
            </s-box>
          </s-stack>
        </s-section>
      )}

      {/* How It Works */}
      {canUseAi && (
        <s-section heading="How It Works">
          <s-stack direction="inline" gap="base">
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-text variant="headingSm">1. Customer enters info</s-text>
              <s-text variant="bodySm" tone="subdued">
                Height, weight, body type, and gender
              </s-text>
            </s-box>
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-text variant="headingSm">2. AI analyzes</s-text>
              <s-text variant="bodySm" tone="subdued">
                Estimates body measurements and matches to your size chart
              </s-text>
            </s-box>
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-text variant="headingSm">3. Recommendation</s-text>
              <s-text variant="bodySm" tone="subdued">
                Shows best size with confidence score and alternatives
              </s-text>
            </s-box>
          </s-stack>
        </s-section>
      )}

      {/* Algorithm Selection */}
      {canUseAi && config.enabled && (
        <s-section heading="Algorithm">
          <s-stack direction="block" gap="base">
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-stack direction="block" gap="tight">
                <s-text variant="headingSm">Basic Algorithm</s-text>
                <s-text variant="bodySm" tone="subdued">
                  Statistical body proportion model. Uses height, weight, and body type
                  to estimate measurements and match to your size chart. Fast, accurate, no API costs.
                </s-text>
                <s-text variant="bodySm" tone="success">
                  {config.algorithm === "basic" ? "Currently active" : "Available"}
                </s-text>
              </s-stack>
            </s-box>

            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-stack direction="block" gap="tight">
                <s-text variant="headingSm">Advanced ML Algorithm</s-text>
                <s-text variant="bodySm" tone="subdued">
                  Machine learning model that improves over time using your store's return data.
                  Adjusts recommendations based on actual fit outcomes.
                </s-text>
                {canUseAdvanced ? (
                  <s-text variant="bodySm" tone="success">
                    {config.algorithm === "advanced" ? "Currently active" : "Available"}
                  </s-text>
                ) : (
                  <s-text variant="bodySm" tone="caution">
                    Requires Pro plan — $19.99/mo
                  </s-text>
                )}
              </s-stack>
            </s-box>
          </s-stack>
        </s-section>
      )}

      {/* Body Types Configuration */}
      {canUseAi && config.enabled && (
        <s-section heading="Supported Body Types">
          <s-paragraph>
            These body types are shown to customers in the recommendation form.
            Each body type adjusts the measurement estimation for more accurate results.
          </s-paragraph>
          <s-stack direction="inline" gap="base">
            {["Slim", "Regular", "Athletic", "Plus"].map((type) => (
              <s-box
                key={type}
                padding="base"
                borderWidth="base"
                borderRadius="base"
              >
                <s-text variant="headingSm">{type}</s-text>
                <s-text variant="bodySm" tone="subdued">
                  {type === "Slim" && "Narrower proportions, fitted preferences"}
                  {type === "Regular" && "Standard proportions, true-to-size"}
                  {type === "Athletic" && "Broader chest/shoulders, narrower waist"}
                  {type === "Plus" && "Fuller proportions, relaxed fit preferences"}
                </s-text>
              </s-box>
            ))}
          </s-stack>
        </s-section>
      )}

      <s-section slot="aside" heading="Current Plan">
        <s-stack direction="block" gap="tight">
          <s-text variant="headingSm">{plan.name}</s-text>
          <s-text variant="bodySm" tone="subdued">
            {canUseAi ? "AI features included" : "AI features not included"}
          </s-text>
          {!canUseAdvanced && canUseAi && (
            <s-button href="/app/pricing" size="slim">
              Upgrade for Advanced AI
            </s-button>
          )}
        </s-stack>
      </s-section>

      <s-section slot="aside" heading="Performance">
        <s-unordered-list>
          <s-list-item>Basic: ~5ms response time, $0/use</s-list-item>
          <s-list-item>Advanced: ~50ms response time, $0/use</s-list-item>
          <s-list-item>All computation server-side</s-list-item>
          <s-list-item>No external API calls required</s-list-item>
        </s-unordered-list>
      </s-section>
    </s-page>
  );
}

