          <s-stack direction="block" gap="base">
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-stack direction="block" gap="tight">
                <s-text variant="headingSm">Basic Algorithm</s-text>
                <s-text variant="bodySm" tone="subdued">
                  Statistical body proportion model. Uses height, weight, and body type
                  to estimate measurements and match to your size chart. Fast, accurate, no API costs.
                </s-text>
                <s-text variant="bodySm" tone="success">
                  {config.algorithm === "basic" ? "Currently active" : "Available"}
