              <s-stack direction="block" gap="tight">
                <s-text variant="headingSm">Advanced ML Algorithm</s-text>
                <s-text variant="bodySm" tone="subdued">
                  Machine learning model that improves over time using your store's return data.
                  Adjusts recommendations based on actual fit outcomes.
                </s-text>
                {canUseAdvanced ? (
                  <s-text variant="bodySm" tone="success">
                    {config.algorithm === "advanced" ? "Currently active" : "Available"}
                  </s-text>
                ) : (
                  <s-text variant="bodySm" tone="caution">
                    Requires Pro plan — $19.99/mo
                  </s-text>
                )}
              </s-stack>
            </s-box>
          </s-stack>
        </s-section>
      )}

      {/* Body Types Configuration */}
      {canUseAi && config.enabled && (
        <s-section heading="Supported Body Types">
          <s-paragraph>
            These body types are shown to customers in the recommendation form.
            Each body type adjusts the measurement estimation for more accurate results.
