import type { LoaderFunctionArgs } from "react-router";
import { useLoaderData } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan, hasFeature } from "../lib/plans";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const [subscription, totalViews, totalClicks, totalRecommendations, totalConverts, topCharts] =
    await Promise.all([
      db.subscription.findUnique({ where: { shop } }),
      db.analyticsEvent.count({ where: { shop, eventType: "view" } }),
      db.analyticsEvent.count({ where: { shop, eventType: "click" } }),
      db.analyticsEvent.count({ where: { shop, eventType: "recommend" } }),
      db.analyticsEvent.count({ where: { shop, eventType: "convert" } }),
      db.analyticsEvent.groupBy({
        by: ["sizeChartId"],
        where: { shop, eventType: "view", sizeChartId: { not: null } },
        _count: { id: true },
        orderBy: { _count: { id: "desc" } },
        take: 5,
      }),
    ]);

  const plan = getPlan(subscription?.planId ?? "free");
  const canViewAnalytics = hasFeature(plan.id, "analytics");

  // Get chart names for top charts
  const chartIds = topCharts
    .map((tc) => tc.sizeChartId)
    .filter((id): id is string => id !== null);

  const charts = chartIds.length > 0
    ? await db.sizeChart.findMany({
        where: { id: { in: chartIds }, shop },
        select: { id: true, name: true },
      })
    : [];

  const topChartsWithNames = topCharts.map((tc) => ({
    chartId: tc.sizeChartId,
    chartName: charts.find((c) => c.id === tc.sizeChartId)?.name ?? "Unknown",
    views: tc._count.id,
  }));

  const clickRate = totalViews > 0 ? ((totalClicks / totalViews) * 100).toFixed(1) : "0";
  const recommendRate = totalClicks > 0 ? ((totalRecommendations / totalClicks) * 100).toFixed(1) : "0";
  const convertRate = totalRecommendations > 0 ? ((totalConverts / totalRecommendations) * 100).toFixed(1) : "0";

  return {
    plan,
    canViewAnalytics,
    stats: {
      totalViews,
      totalClicks,
      totalRecommendations,
      totalConverts,
      clickRate,
      recommendRate,
      convertRate,
    },
    topChartsWithNames,
  };
};

export default function Analytics() {
  const { plan, canViewAnalytics, stats, topChartsWithNames } =
    useLoaderData<typeof loader>();

  if (!canViewAnalytics) {
    return (
      <s-page heading="Analytics">
        <s-section>
          <s-box padding="loose-200">
            <s-stack direction="block" gap="base">
              <s-text variant="headingMd">Unlock Analytics Dashboard</s-text>
              <s-paragraph>
                Track how customers interact with your size charts. See views,
                click-through rates, recommendation accuracy, and which charts
                drive the most conversions.
              </s-paragraph>
              <s-paragraph>
                Available on Growth plan ($9.99/mo) and above.
              </s-paragraph>
              <s-button href="/app/pricing" variant="primary">
                Upgrade to Growth
              </s-button>
            </s-stack>
          </s-box>
        </s-section>
      </s-page>
    );
  }

  return (
    <s-page heading="Analytics">
      {/* Overview Stats */}
      <s-section heading="Overview">
        <s-stack direction="inline" gap="base">
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-text variant="headingLg">{stats.totalViews}</s-text>
            <s-text variant="bodySm" tone="subdued">Chart Views</s-text>
          </s-box>
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-text variant="headingLg">{stats.totalClicks}</s-text>
            <s-text variant="bodySm" tone="subdued">Chart Interactions</s-text>
          </s-box>
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-text variant="headingLg">{stats.totalRecommendations}</s-text>
            <s-text variant="bodySm" tone="subdued">AI Recommendations</s-text>
          </s-box>
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-text variant="headingLg">{stats.totalConverts}</s-text>
            <s-text variant="bodySm" tone="subdued">Conversions</s-text>
          </s-box>
        </s-stack>
      </s-section>

      {/* Conversion Funnel */}
      <s-section heading="Conversion Funnel">
        <s-stack direction="inline" gap="base">
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-text variant="headingLg">{stats.clickRate}%</s-text>
            <s-text variant="bodySm" tone="subdued">
              Click Rate (views → interactions)
            </s-text>
          </s-box>
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-text variant="headingLg">{stats.recommendRate}%</s-text>
            <s-text variant="bodySm" tone="subdued">
              Recommendation Rate (clicks → AI recs)
            </s-text>
          </s-box>
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-text variant="headingLg">{stats.convertRate}%</s-text>
            <s-text variant="bodySm" tone="subdued">
              Convert Rate (recs → add to cart)
            </s-text>
          </s-box>
        </s-stack>
      </s-section>

      {/* Top Charts */}
      <s-section heading="Top Size Charts by Views">
        {topChartsWithNames.length === 0 ? (
          <s-box padding="base">
            <s-text variant="bodySm" tone="subdued">
              No chart views yet. Data will appear once customers start viewing your size charts.
            </s-text>
          </s-box>
        ) : (
          <s-stack direction="block" gap="tight">
            {topChartsWithNames.map((chart, i) => (
              <s-box key={chart.chartId ?? i} padding="base" borderWidth="base" borderRadius="base">
                <s-stack direction="inline" gap="base">
                  <s-text variant="headingSm">#{i + 1}</s-text>
                  <s-stack direction="block" gap="none" style={{ flex: 1 }}>
                    <s-text variant="headingSm">{chart.chartName}</s-text>
                    <s-text variant="bodySm" tone="subdued">
                      {chart.views} view{chart.views !== 1 ? "s" : ""}
                    </s-text>
                  </s-stack>
                </s-stack>
              </s-box>
            ))}
          </s-stack>
        )}
      </s-section>

      <s-section slot="aside" heading="Insights">
        <s-unordered-list>
          <s-list-item>Charts with high views but low clicks may need better positioning</s-list-item>
          <s-list-item>High recommendation usage correlates with lower return rates</s-list-item>
          <s-list-item>Track conversion rate to measure ROI of size recommendations</s-list-item>
        </s-unordered-list>
      </s-section>

      <s-section slot="aside" heading="Plan">
        <s-text variant="bodySm" tone="subdued">{plan.name} Plan</s-text>
        {!hasFeature(plan.id, "returnAttribution") && (
          <s-stack direction="block" gap="tight">
            <s-text variant="bodySm" tone="caution">
              Return Attribution available on Pro plan
            </s-text>
            <s-button href="/app/pricing" size="slim">
              Upgrade to Pro
            </s-button>
          </s-stack>
        )}
      </s-section>
    </s-page>
  );
}

