import db from "../db.server";
import { PLANS, getPlan } from "../lib/plans";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const subscription = await db.subscription.findUnique({ where: { shop } });
  const currentPlan = getPlan(subscription?.planId ?? "free");

  return { currentPlan, plans: PLANS };
};

export default function Pricing() {
  const { currentPlan, plans } = useLoaderData<typeof loader>();

  return (
    <s-page heading="Plans & Pricing">
      <s-section>
        <s-stack direction="block" gap="base">
          <s-text variant="headingMd">
            Simple, transparent pricing. No per-order fees. No hidden charges. Ever.
          </s-text>
          <s-text variant="bodySm" tone="subdued">
            Current plan: {currentPlan.name}
            {currentPlan.price > 0 ? ` ($${currentPlan.price}/mo)` : " (Free)"}
          </s-text>
        </s-stack>
      </s-section>

      <s-section>
        <s-stack direction="inline" gap="base">
          {plans.map((plan) => {
            const isCurrent = plan.id === currentPlan.id;
            const isUpgrade = plans.indexOf(plan) > plans.indexOf(currentPlan);

            return (
              <s-box
                key={plan.id}
                padding="base"
                borderWidth="base"
                borderRadius="base"
                background={isCurrent ? "subdued" : undefined}
              >
                <s-stack direction="block" gap="base">
                  {/* Plan Header */}
                  <s-stack direction="block" gap="tight">
                    <s-text variant="headingMd">{plan.name}</s-text>
                    <s-text variant="headingLg">
                      {plan.price === 0 ? "Free" : `$${plan.price}`}
                      {plan.price > 0 && (
                        <s-text variant="bodySm" tone="subdued">
                          /month
                        </s-text>
                      )}
                    </s-text>
                    {plan.price > 0 && (
                      <s-text variant="bodySm" tone="subdued">
                        or ${plan.annualPrice}/year (save 20%)
                      </s-text>
                    )}
                  </s-stack>

                  {/* Features */}
                  <s-unordered-list>
                    {plan.features.map((feature, i) => (
                      <s-list-item key={i}>{feature}</s-list-item>
                    ))}
                  </s-unordered-list>

                  {/* CTA */}
                  {isCurrent ? (
                    <s-button disabled>Current Plan</s-button>
                  ) : isUpgrade ? (
                    <s-button variant="primary">
                      Upgrade to {plan.name}
                    </s-button>
                  ) : (
                    <s-button variant="tertiary">
                      Downgrade to {plan.name}
                    </s-button>
                  )}
                </s-stack>
              </s-box>
            );
          })}
        </s-stack>
      </s-section>

      {/* Comparison Highlights */}
      <s-section heading="Why Merchants Switch to Us">
        <s-stack direction="inline" gap="base">
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-text variant="headingSm">No Per-Order Fees</s-text>
            <s-text variant="bodySm" tone="subdued">
              Unlike competitors who charge per order on ALL orders, we use simple flat pricing. Your cost never surprises you.
            </s-text>
          </s-box>
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-text variant="headingSm">No Watermark on Free</s-text>
            <s-text variant="bodySm" tone="subdued">
              Even our free plan has no watermark or branding. Your store stays clean and professional.
            </s-text>
          </s-box>
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-text variant="headingSm">20% Annual Discount</s-text>
            <s-text variant="bodySm" tone="subdued">
              Pay annually and save 2 months. No commitment — cancel anytime and keep access until period ends.
            </s-text>
          </s-box>
        </s-stack>
      </s-section>

      <s-section slot="aside" heading="FAQ">
        <s-stack direction="block" gap="base">
          <s-stack direction="block" gap="tight">
            <s-text variant="headingSm">Can I switch plans anytime?</s-text>
            <s-text variant="bodySm" tone="subdued">
              Yes. Upgrade instantly, downgrade at end of billing period. No lock-in.
            </s-text>
          </s-stack>
          <s-stack direction="block" gap="tight">
            <s-text variant="headingSm">What happens to my charts if I downgrade?</s-text>
            <s-text variant="bodySm" tone="subdued">
              Your charts are never deleted. On Free, only the 3 most recent stay published — the rest become drafts.
            </s-text>
          </s-stack>
          <s-stack direction="block" gap="tight">
            <s-text variant="headingSm">Is there a free trial?</s-text>
            <s-text variant="bodySm" tone="subdued">
              The free plan is permanent — not a trial. Upgrade only when you need more features.
            </s-text>
          </s-stack>
        </s-stack>
      </s-section>
    </s-page>
  );
}

