import { useEffect } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import db from "../db.server";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const [chartCount, subscription] = await Promise.all([
    db.sizeChart.count({ where: { shop } }),
    db.subscription.findUnique({ where: { shop } }),
  ]);

  return {
    shop,
    chartCount,
    planId: subscription?.planId ?? "free",
    status: subscription?.status ?? "active",
  };
};

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    switch (intent) {
      case "export-data": {
        const charts = await db.sizeChart.findMany({
          where: { shop },
          include: { assignments: true },
        });
        return { ok: true, message: `Export ready: ${charts.length} charts`, exportData: JSON.stringify(charts, null, 2) };
      }

      case "reset-widget": {
        await db.widgetConfig.deleteMany({ where: { shop } });
        return { ok: true, message: "Widget settings reset to defaults" };
      }

      case "reset-analytics": {
        await db.analyticsEvent.deleteMany({ where: { shop } });
        return { ok: true, message: "Analytics data cleared" };
      }

      default:
        return { error: "Unknown action" };
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : "An unexpected error occurred";
    return { error: message };
  }
};

export default function Settings() {
  const { shop, chartCount, planId, status } = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();

  useEffect(() => {
    if (fetcher.data && "ok" in fetcher.data && fetcher.data.ok) {
      shopify.toast.show(fetcher.data.message ?? "Done");
    } else if (fetcher.data && "error" in fetcher.data) {
      shopify.toast.show(fetcher.data.error ?? "Error", { isError: true });
    }
  }, [fetcher.data, shopify]);

  const isLoading = fetcher.state !== "idle";

  return (
    <s-page heading="Settings">
      {/* Account Info */}
      <s-section heading="Account">
        <s-stack direction="block" gap="tight">
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="inline" gap="base">
              <s-stack direction="block" gap="none">
                <s-text variant="bodySm" tone="subdued">Store</s-text>
                <s-text variant="headingSm">{shop}</s-text>
              </s-stack>
              <s-stack direction="block" gap="none">
                <s-text variant="bodySm" tone="subdued">Plan</s-text>
                <s-text variant="headingSm">{planId} ({status})</s-text>
              </s-stack>
              <s-stack direction="block" gap="none">
                <s-text variant="bodySm" tone="subdued">Size Charts</s-text>
                <s-text variant="headingSm">{chartCount}</s-text>
              </s-stack>
            </s-stack>
          </s-box>
        </s-stack>
      </s-section>

      {/* Data Management */}
      <s-section heading="Data Management">
        <s-stack direction="block" gap="base">
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="tight">
              <s-text variant="headingSm">Export Size Charts</s-text>
              <s-text variant="bodySm" tone="subdued">
                Download all your size charts as JSON data. Useful for backup or migration.
              </s-text>
              <fetcher.Form method="post">
                <input type="hidden" name="intent" value="export-data" />
                <s-button submit loading={isLoading}>
                  Export Data
                </s-button>
              </fetcher.Form>
            </s-stack>
          </s-box>
        </s-stack>
      </s-section>

      {/* Reset Options */}
      <s-section heading="Reset">
        <s-stack direction="block" gap="base">
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="tight">
              <s-text variant="headingSm">Reset Widget Settings</s-text>
              <s-text variant="bodySm" tone="subdued">
                Restore widget appearance to default settings. Your size charts and data are not affected.
              </s-text>
              <fetcher.Form method="post">
                <input type="hidden" name="intent" value="reset-widget" />
                <s-button submit tone="critical" loading={isLoading}>
                  Reset Widget
                </s-button>
              </fetcher.Form>
            </s-stack>
          </s-box>

          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="tight">
              <s-text variant="headingSm">Clear Analytics Data</s-text>
              <s-text variant="bodySm" tone="subdued">
                Remove all analytics events. This cannot be undone. Your size charts and settings are not affected.
              </s-text>
              <fetcher.Form method="post">
                <input type="hidden" name="intent" value="reset-analytics" />
                <s-button submit tone="critical" loading={isLoading}>
                  Clear Analytics
                </s-button>
              </fetcher.Form>
            </s-stack>
          </s-box>
        </s-stack>
      </s-section>

      <s-section slot="aside" heading="Support">
        <s-stack direction="block" gap="tight">
          <s-text variant="bodySm" tone="subdued">
            Need help? We respond within 2 hours during business hours.
          </s-text>
          <s-unordered-list>
            <s-list-item>
              <s-link href="mailto:support@sizechartapp.com" target="_blank">
                Email Support
              </s-link>
            </s-list-item>
            <s-list-item>
              <s-link href="https://docs.sizechartapp.com" target="_blank">
                Documentation
              </s-link>
            </s-list-item>
          </s-unordered-list>
        </s-stack>
      </s-section>

      <s-section slot="aside" heading="App Version">
        <s-text variant="bodySm" tone="subdued">v1.0.0</s-text>
        <s-text variant="bodySm" tone="subdued">Built for Shopify</s-text>
      </s-section>
    </s-page>
  );
}

