                      {chart.assignments.length} assignment
                      {chart.assignments.length !== 1 ? "s" : ""}
                    </s-text>
                  </s-stack>
                  <s-stack direction="inline" gap="tight">
                    <fetcher.Form method="post">
                      <input type="hidden" name="intent" value="toggle-status" />
                      <input type="hidden" name="id" value={chart.id} />
                      <s-button submit size="slim" loading={isLoading}>
                        {chart.status === "active" ? "Unpublish" : "Publish"}
                      </s-button>
                    </fetcher.Form>
                    <fetcher.Form method="post">
                      <input type="hidden" name="intent" value="duplicate" />
                      <input type="hidden" name="id" value={chart.id} />
                      <s-button submit size="slim" loading={isLoading}>
                        Duplicate
                      </s-button>
                    </fetcher.Form>
                    <fetcher.Form method="post">
                      <input type="hidden" name="intent" value="delete" />
                      <input type="hidden" name="id" value={chart.id} />
                      <s-button submit size="slim" variant="tertiary" tone="critical" loading={isLoading}>
