import { useEffect } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan, hasFeature } from "../lib/plans";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const [config, subscription] = await Promise.all([
    db.recommenderConfig.findUnique({ where: { shop } }),
    db.subscription.findUnique({ where: { shop } }),
  ]);

  const plan = getPlan(subscription?.planId ?? "free");

  return {
    config: config ?? { enabled: false, algorithm: "basic", bodyTypes: "[]", sizingRules: "{}" },
    plan,
    canUseAi: hasFeature(plan.id, "aiRecommender"),
    canUseAdvanced: hasFeature(plan.id, "advancedAi"),
  };
};

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    switch (intent) {
      case "toggle": {
        const subscription = await db.subscription.findUnique({ where: { shop } });
        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
          return { error: "AI recommender requires Growth plan or higher" };
        }
        const current = await db.recommenderConfig.findUnique({ where: { shop } });
        await db.recommenderConfig.upsert({
          where: { shop },
          update: { enabled: !current?.enabled },
          create: { shop, enabled: true },
        });
        return { ok: true, message: current?.enabled ? "AI Recommender disabled" : "AI Recommender enabled" };
      }
      default:
        return { error: "Unknown action" };
    }
  } catch (error) {
    return { error: error instanceof Error ? error.message : "An unexpected error occurred" };
  }
};

export default function Recommender() {
  const { config, plan, canUseAi, canUseAdvanced } = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();

  useEffect(() => {
    if (fetcher.data && "ok" in fetcher.data) shopify.toast.show(fetcher.data.message ?? "Success");
    else if (fetcher.data && "error" in fetcher.data) shopify.toast.show(fetcher.data.error ?? "Error", { isError: true });
  }, [fetcher.data, shopify]);

  const isLoading = fetcher.state !== "idle";

  return (
    <s-page heading="AI Size Recommender">
      {!canUseAi && (
        <s-section>
          <s-box padding="base" borderWidth="base" borderRadius="base" background="subdued">
            <s-stack direction="block" gap="base">
              <s-heading>Unlock AI Size Recommendations</s-heading>
              <s-paragraph>
                Help customers find their perfect size with AI-powered recommendations
                based on height, weight, and body type. Available on Growth plan and above.
              </s-paragraph>
              <s-button href="/app/pricing" variant="primary">Upgrade to Growth — $9.99/mo</s-button>
            </s-stack>
          </s-box>
        </s-section>
      )}

      {canUseAi && (
        <s-section heading="Recommender Status">
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-text>Status: {config.enabled ? "Active" : "Disabled"}</s-text>
              <s-text tone="neutral">
                {config.enabled
                  ? "Customers can get AI-powered size recommendations on your storefront"
                  : "Enable to show the 'Find My Size' button on product pages"}
              </s-text>
              <fetcher.Form method="post">
                <input type="hidden" name="intent" value="toggle" />
                <s-button type="submit" variant={config.enabled ? "tertiary" : "primary"} loading={isLoading}>
                  {config.enabled ? "Disable Recommender" : "Enable Recommender"}
                </s-button>
              </fetcher.Form>
            </s-stack>
          </s-box>
        </s-section>
      )}

      {canUseAi && (
        <s-section heading="How It Works">
          <s-stack direction="inline" gap="base">
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-text>1. Customer enters info</s-text>
              <s-text tone="neutral">Height, weight, body type, and gender</s-text>
            </s-box>
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-text>2. AI analyzes</s-text>
              <s-text tone="neutral">Estimates body measurements and matches to your size chart</s-text>
            </s-box>
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-text>3. Recommendation</s-text>
              <s-text tone="neutral">Shows best size with confidence score and alternatives</s-text>
            </s-box>
          </s-stack>
        </s-section>
      )}

      {canUseAi && config.enabled && (
        <s-section heading="Algorithm">
          <s-stack direction="block" gap="base">
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-text>Basic Algorithm</s-text>
              <s-text tone="neutral">
                Statistical body proportion model. Fast, accurate, no API costs.
              </s-text>
              <s-text tone="success">{config.algorithm === "basic" ? "Currently active" : "Available"}</s-text>
            </s-box>
            <s-box padding="base" borderWidth="base" borderRadius="base">
              <s-text>Advanced ML Algorithm</s-text>
              <s-text tone="neutral">
                Improves over time using your store's return data.
              </s-text>
              {canUseAdvanced
                ? <s-text tone="success">{config.algorithm === "advanced" ? "Currently active" : "Available"}</s-text>
                : <s-text tone="caution">Requires Pro plan — $19.99/mo</s-text>
              }
            </s-box>
          </s-stack>
        </s-section>
      )}

      {canUseAi && config.enabled && (
        <s-section heading="Supported Body Types">
          <s-paragraph>These body types are shown to customers in the recommendation form.</s-paragraph>
          <s-stack direction="inline" gap="base">
            {[
              { name: "Slim", desc: "Narrower proportions, fitted preferences" },
              { name: "Regular", desc: "Standard proportions, true-to-size" },
              { name: "Athletic", desc: "Broader chest/shoulders, narrower waist" },
              { name: "Plus", desc: "Fuller proportions, relaxed fit preferences" },
            ].map((type) => (
              <s-box key={type.name} padding="base" borderWidth="base" borderRadius="base">
                <s-text>{type.name}</s-text>
                <s-text tone="neutral">{type.desc}</s-text>
              </s-box>
            ))}
          </s-stack>
        </s-section>
      )}

      <s-section slot="aside" heading="Current Plan">
        <s-stack direction="block" gap="small-200">
          <s-text>{plan.name}</s-text>
          <s-text tone="neutral">{canUseAi ? "AI features included" : "AI features not included"}</s-text>
          {!canUseAdvanced && canUseAi && (
            <s-button href="/app/pricing">Upgrade for Advanced AI</s-button>
          )}
        </s-stack>
      </s-section>

      <s-section slot="aside" heading="Performance">
        <s-unordered-list>
          <s-list-item>Basic: ~5ms response time, $0/use</s-list-item>
          <s-list-item>Advanced: ~50ms, $0/use</s-list-item>
          <s-list-item>All computation server-side</s-list-item>
        </s-unordered-list>
      </s-section>
    </s-page>
  );
}

