        <s-unordered-list>
          <s-list-item>Basic: ~5ms response time, $0/use</s-list-item>
          <s-list-item>Advanced: ~50ms response time, $0/use</s-list-item>
          <s-list-item>All computation server-side</s-list-item>
          <s-list-item>No external API calls required</s-list-item>
        </s-unordered-list>
      </s-section>
