import { useEffect } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import db from "../db.server";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const [chartCount, subscription] = await Promise.all([
    db.sizeChart.count({ where: { shop } }),
    db.subscription.findUnique({ where: { shop } }),
  ]);

  return {
    shop,
    chartCount,
    planId: subscription?.planId ?? "free",
    status: subscription?.status ?? "active",
  };
};

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;
  const formData = await request.formData();
  const intent = formData.get("intent") as string;

  try {
    switch (intent) {
      case "export-data": {
        const charts = await db.sizeChart.findMany({ where: { shop }, include: { assignments: true } });
        return { ok: true, message: `Export ready: ${charts.length} charts` };
      }
      case "reset-widget": {
        await db.widgetConfig.deleteMany({ where: { shop } });
        return { ok: true, message: "Widget settings reset to defaults" };
      }
      case "reset-analytics": {
        await db.analyticsEvent.deleteMany({ where: { shop } });
        return { ok: true, message: "Analytics data cleared" };
      }
      default:
        return { error: "Unknown action" };
    }
  } catch (error) {
    return { error: error instanceof Error ? error.message : "An unexpected error occurred" };
  }
};

export default function Settings() {
  const { shop, chartCount, planId, status } = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();

  useEffect(() => {
    if (fetcher.data && "ok" in fetcher.data) shopify.toast.show(fetcher.data.message ?? "Done");
    else if (fetcher.data && "error" in fetcher.data) shopify.toast.show(fetcher.data.error ?? "Error", { isError: true });
  }, [fetcher.data, shopify]);

  const isLoading = fetcher.state !== "idle";

  return (
    <s-page heading="Settings">
      <s-section heading="Account">
        <s-box padding="base" borderWidth="base" borderRadius="base">
          <s-stack direction="inline" gap="base">
            <s-stack direction="block" gap="small-100">
              <s-text tone="neutral">Store</s-text>
              <s-text>{shop}</s-text>
            </s-stack>
            <s-stack direction="block" gap="small-100">
              <s-text tone="neutral">Plan</s-text>
              <s-text>{planId} ({status})</s-text>
            </s-stack>
            <s-stack direction="block" gap="small-100">
              <s-text tone="neutral">Size Charts</s-text>
              <s-text>{chartCount}</s-text>
            </s-stack>
          </s-stack>
        </s-box>
      </s-section>

      <s-section heading="Data Management">
        <s-box padding="base" borderWidth="base" borderRadius="base">
          <s-stack direction="block" gap="small-200">
            <s-text>Export Size Charts</s-text>
            <s-text tone="neutral">Download all your size charts as JSON data for backup or migration.</s-text>
            <fetcher.Form method="post">
              <input type="hidden" name="intent" value="export-data" />
              <s-button type="submit" loading={isLoading}>Export Data</s-button>
            </fetcher.Form>
          </s-stack>
        </s-box>
      </s-section>

      <s-section heading="Reset">
        <s-stack direction="block" gap="base">
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-text>Reset Widget Settings</s-text>
              <s-text tone="neutral">Restore widget appearance to defaults. Charts and data are not affected.</s-text>
              <fetcher.Form method="post">
                <input type="hidden" name="intent" value="reset-widget" />
                <s-button type="submit" tone="critical" loading={isLoading}>Reset Widget</s-button>
              </fetcher.Form>
            </s-stack>
          </s-box>

          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-text>Clear Analytics Data</s-text>
              <s-text tone="neutral">Remove all analytics events. This cannot be undone.</s-text>
              <fetcher.Form method="post">
                <input type="hidden" name="intent" value="reset-analytics" />
                <s-button type="submit" tone="critical" loading={isLoading}>Clear Analytics</s-button>
              </fetcher.Form>
            </s-stack>
          </s-box>
        </s-stack>
      </s-section>

      <s-section slot="aside" heading="Support">
        <s-stack direction="block" gap="small-200">
          <s-text tone="neutral">Need help? We respond within 2 hours.</s-text>
          <s-unordered-list>
            <s-list-item>
              <s-link href="mailto:support@sizechartapp.com" target="_blank">Email Support</s-link>
            </s-list-item>
          </s-unordered-list>
        </s-stack>
      </s-section>

      <s-section slot="aside" heading="App Version">
        <s-text tone="neutral">v1.0.0</s-text>
        <s-text tone="neutral">Built for Shopify</s-text>
      </s-section>
    </s-page>
  );
}

