import { useEffect } from "react";
import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
import { useLoaderData, useFetcher } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import db from "../db.server";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const config = await db.widgetConfig.findUnique({ where: { shop: session.shop } });

  return {
    config: config ?? {
      displayMode: "popup", position: "bottom-right", triggerType: "button",
      primaryColor: "#000000", successColor: "#16a34a", errorColor: "#dc2626",
      backgroundColor: "#ffffff", textColor: "#111111", borderRadius: "8",
      heading: "Size Guide", placeholder: "Select your size", buttonText: "Find My Size",
      successMessage: "This size should fit you well!",
      errorMessage: "We couldn't determine your size. Please refer to the chart.",
      showRecommender: true, customCss: "",
    },
  };
};

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();

  try {
    const data = {
      displayMode: (formData.get("displayMode") as string) || "popup",
      position: (formData.get("position") as string) || "bottom-right",
      triggerType: (formData.get("triggerType") as string) || "button",
      primaryColor: (formData.get("primaryColor") as string) || "#000000",
      successColor: (formData.get("successColor") as string) || "#16a34a",
      errorColor: (formData.get("errorColor") as string) || "#dc2626",
      backgroundColor: (formData.get("backgroundColor") as string) || "#ffffff",
      textColor: (formData.get("textColor") as string) || "#111111",
      borderRadius: (formData.get("borderRadius") as string) || "8",
      heading: (formData.get("heading") as string) || "Size Guide",
      placeholder: (formData.get("placeholder") as string) || "Select your size",
      buttonText: (formData.get("buttonText") as string) || "Find My Size",
      successMessage: (formData.get("successMessage") as string) || "This size should fit you well!",
      errorMessage: (formData.get("errorMessage") as string) || "We couldn't determine your size.",
      showRecommender: formData.get("showRecommender") === "true",
      customCss: (formData.get("customCss") as string) || "",
    };

    await db.widgetConfig.upsert({
      where: { shop: session.shop },
      update: data,
      create: { shop: session.shop, ...data },
    });
    return { ok: true, message: "Widget settings saved" };
  } catch (error) {
    return { error: error instanceof Error ? error.message : "An unexpected error occurred" };
  }
};

export default function Widget() {
  const { config } = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();

  useEffect(() => {
    if (fetcher.data && "ok" in fetcher.data) shopify.toast.show(fetcher.data.message ?? "Saved");
    else if (fetcher.data && "error" in fetcher.data) shopify.toast.show(fetcher.data.error ?? "Error", { isError: true });
  }, [fetcher.data, shopify]);

  const isLoading = fetcher.state !== "idle";

  return (
    <s-page heading="Widget Customizer">
      <fetcher.Form method="post">
        <s-section heading="Display Mode">
          <s-stack direction="inline" gap="base">
            {[
              { value: "popup", label: "Popup", desc: "Opens as a modal overlay" },
              { value: "inline", label: "Inline", desc: "Embedded in the product page" },
              { value: "both", label: "Both", desc: "Inline preview with popup for full chart" },
            ].map((mode) => (
              <s-box key={mode.value} padding="base" borderWidth="base" borderRadius="base">
                <label>
                  <input type="radio" name="displayMode" value={mode.value} defaultChecked={config.displayMode === mode.value} />
                  {" "}{mode.label}
                  <br />
                  <s-text tone="neutral">{mode.desc}</s-text>
                </label>
              </s-box>
            ))}
          </s-stack>
        </s-section>

        <s-section heading="Popup Position">
          <s-stack direction="inline" gap="base">
            {["bottom-right", "bottom-left", "top-right", "top-left"].map((pos) => (
              <label key={pos}>
                <input type="radio" name="position" value={pos} defaultChecked={config.position === pos} />
                {" "}{pos.replace("-", " ")}
              </label>
            ))}
          </s-stack>
          <input type="hidden" name="triggerType" value={config.triggerType} />
        </s-section>

        <s-section heading="Colors">
          <s-stack direction="inline" gap="base">
            {[
              { name: "primaryColor", label: "Primary" },
              { name: "successColor", label: "Success" },
              { name: "errorColor", label: "Error" },
              { name: "backgroundColor", label: "Background" },
              { name: "textColor", label: "Text" },
            ].map((c) => (
              <s-box key={c.name} padding="base" borderWidth="base" borderRadius="base">
                <label>
                  <s-text>{c.label}</s-text>
                  <br />
                  <input type="color" name={c.name} defaultValue={(config as Record<string, string>)[c.name]} />
                </label>
              </s-box>
            ))}
          </s-stack>
        </s-section>

        <s-section heading="Text & Messages">
          <s-stack direction="block" gap="base">
            {[
              { name: "heading", label: "Widget Heading" },
              { name: "buttonText", label: "Button Text" },
              { name: "successMessage", label: "Success Message" },
              { name: "errorMessage", label: "Error Message" },
            ].map((field) => (
              <label key={field.name}>
                <s-text>{field.label}</s-text>
                <br />
                <input
                  type="text"
                  name={field.name}
                  defaultValue={(config as Record<string, string>)[field.name]}
                  style={{ width: "100%", padding: "8px", borderRadius: "4px", border: "1px solid #ccc" }}
                />
              </label>
            ))}
            <input type="hidden" name="placeholder" value={config.placeholder} />
